import{_ as a,c as e,o as d,b0 as s}from"./chunks/framework.C5ev1SXp.js";const i="/scm-docs/assets/image-20261015064336492.BT4SgL1Q.png",r="/scm-docs/assets/hw-fsmc-layout.B43ax4Fy.svg",n="/scm-docs/assets/image-20261015064648517.Clh0q09m.png",l="/scm-docs/assets/image-20261015065116793.B-Y-H1SW.png",o="/scm-docs/assets/image-20261015065140785.DRzxT7bp.png",_=JSON.parse('{"title":"LV001-以太网与DM9000硬件接口","description":null,"frontmatter":{"title":"LV001-以太网与DM9000硬件接口","date":"2026-10-14T21:35:41.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/ethernet/126d628e13a516684ed019b4","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-14T21:35:41.358Z","fulluuid":"84ed019b4d0545ff950364580ff204da","useduuid":"84ed019b4"}},"headers":[],"relativePath":"sdoc/advanced-chapter/ethernet/126d628e13a516684ed019b4.md","filePath":"sdoc/30-进阶篇/06-以太网/LV001-以太网与DM9000硬件接口.md","lastUpdated":1792231946000}'),h={name:"sdoc/advanced-chapter/ethernet/126d628e13a516684ed019b4.md"};function c(p,t,E,k,b,D){return d(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="lv001-以太网与dm9000硬件接口" tabindex="-1">LV001-以太网与DM9000硬件接口 <a class="header-anchor" href="#lv001-以太网与dm9000硬件接口" aria-label="Permalink to &quot;LV001-以太网与DM9000硬件接口&quot;">​</a></h1><blockquote><p><strong>前置阅读</strong>：建议先看<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0077c57a0b5fb.html">网络基础</a>系列的十篇（分层模型 → 封装与帧 → IP 与掩码 → 网关 → 交换机与路由器 → ARP → 传输层 → DHCP → 调试工具 → 一次 ping 的旅程），再回到本系列的实现部分。本系列讲&quot;怎么把它做出来&quot;，那十篇讲&quot;它到底是什么&quot;。</p></blockquote><h2 id="一、-以太网接入单片机的两条路" tabindex="-1">一、 以太网接入单片机的两条路 <a class="header-anchor" href="#一、-以太网接入单片机的两条路" aria-label="Permalink to &quot;一、 以太网接入单片机的两条路&quot;">​</a></h2><p>给单片机接网线，业界有两条完全不同的路：</p><table tabindex="0"><thead><tr><th>方案</th><th>协议栈跑在哪</th><th>代表芯片</th><th>MCU 侧要做的事</th></tr></thead><tbody><tr><td>全硬件协议栈</td><td>网口芯片内部</td><td>CH395Q</td><td>只管收发数据，不理解 TCP/IP 报文</td></tr><tr><td>软件协议栈</td><td>MCU 上</td><td>DM9000（MAC + PHY）+ lwIP</td><td>自己跑 TCP/IP，控制力强但代码量大</td></tr></tbody></table><p>正点原子的两本手册正好各讲一条：<a href="https://gitee.com/docs-site/scm-reference-guide/raw/main/30-STM32%E8%B5%84%E6%96%99/10-lwIP/%E7%BD%91%E7%BB%9C%E5%BC%80%E5%8F%91%E6%8C%87%E5%8D%97_V1.0.pdf" target="_blank" rel="noreferrer">《网络开发指南》</a>讲的是 CH395Q 这条全硬件路线；<a href="https://gitee.com/docs-site/scm-reference-guide/raw/main/30-STM32%E8%B5%84%E6%96%99/10-lwIP/STM32F1%20LWIP%E5%BC%80%E5%8F%91%E6%89%8B%E5%86%8C%28DM9000%E7%89%88%29_V1.1.pdf" target="_blank" rel="noreferrer">《STM32F1 LWIP 开发手册（DM9000 版）》</a>讲的是 DM9000 + lwIP 这条软件路线。战舰 V3 板载的网口芯片是后者，所以本系列文档都按 DM9000 + lwIP 走。</p><p>选软件协议栈的代价是：协议栈源码要自己搬、自己裁、自己适配；好处是 <code>lwipopts.h</code> 里每一个内存池、每一个协议开关都能按需收紧——这一点在 Bootloader 这种盯着 Flash 和 RAM 的场景里很重要。</p><h2 id="二、-dm9000-芯片与访问方式" tabindex="-1">二、 DM9000 芯片与访问方式 <a class="header-anchor" href="#二、-dm9000-芯片与访问方式" aria-label="Permalink to &quot;二、 DM9000 芯片与访问方式&quot;">​</a></h2><h3 id="_1-一颗-三合一-芯片" tabindex="-1">1. 一颗&quot;三合一&quot;芯片 <a class="header-anchor" href="#_1-一颗-三合一-芯片" aria-label="Permalink to &quot;1. 一颗&quot;三合一&quot;芯片&quot;">​</a></h3><p>DM9000 是一颗 10/100M 自适应的以太网控制器，把 MAC 和 PHY 集成在一颗芯片里：</p><ul><li>片内自带 MAC、PHY 与收发 SRAM（网卡缓冲），外部只需要一颗 25 MHz 晶振和网络隔离变压器（原理图上标为 EARTHNET / MULTI MEDIA DECODER 一带的电路）。</li><li>对外是<strong>并口</strong>：一组数据线 + 一组控制线，MCU 像访问外部存储器一样读写它的寄存器与收发 FIFO。</li><li>芯片身份由 ID 寄存器标识，读到 <code>0x90000A46</code>（VIDL / PIDL / VIDH / PIDH 拼起来）才算认到芯片。</li></ul><h3 id="_2-索引加数据口的访问模型" tabindex="-1">2. 索引加数据口的访问模型 <a class="header-anchor" href="#_2-索引加数据口的访问模型" aria-label="Permalink to &quot;2. 索引加数据口的访问模型&quot;">​</a></h3><p>DM9000 最特别的一点是寄存器访问方式：<strong>它只有一个&quot;寄存器窗口&quot;，想访问哪个寄存器得先报号。</strong></p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>写地址线 A7 = 0  →  命令口：写&quot;要访问哪个寄存器&quot;</span></span>
<span class="line"><span>写地址线 A7 = 1  →  数据口：读/写这个寄存器的内容</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>也就是常说的&quot;索引 + 数据&quot;两个口。一次寄存器访问永远是两步：先写索引，再读写数据。</p><p>正因为它是&quot;并口 + 索引/数据两个地址&quot;的访问方式，把它挂到 FSMC 的某个片选上、用一根地址线区分命令口和数据口，是最省事的接法。驱动的具体实现见 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5187d4be5a1c9.html">LV005-DM9000驱动实现</a> 第二节。</p><h2 id="三、-原理图上的接线" tabindex="-1">三、 原理图上的接线 <a class="header-anchor" href="#三、-原理图上的接线" aria-label="Permalink to &quot;三、 原理图上的接线&quot;">​</a></h2><img src="`+i+'" alt="image-20261015064336492" style="zoom:50%;"><p>翻原理图（<code>WarShip STM32F1_V3.4_SCH.pdf</code>）可以确认：DM9000 的数据与控制线全部接在 STM32 的 FSMC 总线上，只有中断与复位两根线是普通 GPIO。</p><img src="'+r+`" alt="DM9000 与外部 SRAM 在 FSMC 总线上的连接"><h3 id="_1-控制与片选" tabindex="-1">1. 控制与片选 <a class="header-anchor" href="#_1-控制与片选" aria-label="Permalink to &quot;1. 控制与片选&quot;">​</a></h3><table tabindex="0"><thead><tr><th>信号</th><th>STM32 引脚</th><th>引脚号</th><th>片上复用</th><th>说明</th></tr></thead><tbody><tr><td>NET_CS</td><td>PG9</td><td>124</td><td>FSMC_NE2</td><td>FSMC 片选 2，专给 DM9000，官方不建议改作普通 IO</td></tr><tr><td>NET_RD</td><td>PD4</td><td>118</td><td>FSMC_NOE</td><td>与 TFTLCD / IS62WV51216 共用</td></tr><tr><td>NET_WR</td><td>PD5</td><td>119</td><td>FSMC_NWE</td><td>与 TFTLCD / IS62WV51216 共用</td></tr><tr><td>NET_CMD</td><td>PF13</td><td>53</td><td>FSMC_A7</td><td>命令/数据选择线，与 IS62WV51216 共用</td></tr><tr><td>DM9000_INT</td><td>PG6</td><td>91</td><td>—</td><td>中断，与 WIRELESS 接口的 NRF_IRQ 共用</td></tr><tr><td>DM9000_RST</td><td>PD7</td><td>123</td><td>—</td><td>复位，与 RS485_RE 共用</td></tr></tbody></table><h3 id="_2-数据线" tabindex="-1">2. 数据线 <a class="header-anchor" href="#_2-数据线" aria-label="Permalink to &quot;2. 数据线&quot;">​</a></h3><p>16 位总线，D0 ~ D15 分散在 PD 与 PE 口上：</p><table tabindex="0"><thead><tr><th>数据线</th><th>引脚</th><th>引脚号</th><th>数据线</th><th>引脚</th><th>引脚号</th></tr></thead><tbody><tr><td>D0</td><td>PD14</td><td>85</td><td>D8</td><td>PE11</td><td>64</td></tr><tr><td>D1</td><td>PD15</td><td>86</td><td>D9</td><td>PE12</td><td>65</td></tr><tr><td>D2</td><td>PD0</td><td>114</td><td>D10</td><td>PE13</td><td>66</td></tr><tr><td>D3</td><td>PD1</td><td>115</td><td>D11</td><td>PE14</td><td>67</td></tr><tr><td>D4</td><td>PE7</td><td>58</td><td>D12</td><td>PE15</td><td>68</td></tr><tr><td>D5</td><td>PE8</td><td>59</td><td>D13</td><td>PD8</td><td>77</td></tr><tr><td>D6</td><td>PE9</td><td>60</td><td>D14</td><td>PD9</td><td>78</td></tr><tr><td>D7</td><td>PE10</td><td>63</td><td>D15</td><td>PD10</td><td>79</td></tr></tbody></table><p>引脚分配与「完全独立」标记来自配套的<a href="https://gitee.com/docs-site/scm-reference-guide/raw/main/30-STM32%E8%B5%84%E6%96%99/01-ATK%E6%88%98%E8%88%B0-V3%E5%BC%80%E5%8F%91%E6%9D%BF%E5%8E%9F%E7%90%86%E5%9B%BE/%E6%88%98%E8%88%B0V3%20IO%E5%BC%95%E8%84%9A%E5%88%86%E9%85%8D%E8%A1%A8.xlsx" target="_blank" rel="noreferrer">《战舰V3 IO引脚分配表》</a>。<strong>注意 D0~D15、NOE、NWE、A7 都标了 N</strong>：它们被 TFTLCD、IS62WV51216、DM9000 三家共用，只有三家的片选都被禁止时才轮得到当普通 IO。</p><h3 id="_3-两处复用带来的限制" tabindex="-1">3. 两处复用带来的限制 <a class="header-anchor" href="#_3-两处复用带来的限制" aria-label="Permalink to &quot;3. 两处复用带来的限制&quot;">​</a></h3><p>原理图与 IO 分配表都写明了这两处复用，实际用的时候要心里有数：</p><ul><li><strong>PG6 = NRF_IRQ 与 DM9000_INT 共用</strong>。也就是说，一旦把 PG6 配成 DM9000 的中断输入，WIRELESS 接口（NRF 模块）的中断就没法用了——除非你的逻辑能容忍两个中断源混在一根线上。</li><li><strong>PD7 = DM9000_RST 与 RS485_RE 共用</strong>。板子上 DM9000 的复位是<strong>软件可控</strong>的（不像有些设计直接接 VCC），代价是 RS485 的收发使能脚被占掉了。</li></ul><p>这类&quot;引脚复用&quot;的取舍必须在项目初期就定下来，因为它决定了后面能不能同时用这两个外设。</p><h2 id="四、-地址-为什么命令口是-0xfe-数据口是-0x100" tabindex="-1">四、 地址：为什么命令口是 0xFE，数据口是 0x100 <a class="header-anchor" href="#四、-地址-为什么命令口是-0xfe-数据口是-0x100" aria-label="Permalink to &quot;四、 地址：为什么命令口是 0xFE，数据口是 0x100&quot;">​</a></h2><h3 id="_1-fsmc-片选与基址" tabindex="-1">1. FSMC 片选与基址 <a class="header-anchor" href="#_1-fsmc-片选与基址" aria-label="Permalink to &quot;1. FSMC 片选与基址&quot;">​</a></h3><p>STM32 的 FSMC Bank1 划分了四个片选区，每片 64 MB：</p><table tabindex="0"><thead><tr><th>片选</th><th>起始地址</th><th>本板上挂了什么</th></tr></thead><tbody><tr><td>NE1</td><td>0x60000000</td><td>未使用</td></tr><tr><td>NE2</td><td>0x64000000</td><td>DM9000</td></tr><tr><td>NE3</td><td>0x68000000</td><td>外部 SRAM（IS62WV51216）</td></tr><tr><td>NE4</td><td>0x6C000000</td><td>未使用</td></tr></tbody></table><p>DM9000 挂 NE2，所以基址是 <code>0x64000000</code>。</p><h3 id="_2-地址线-a7-区分两个口" tabindex="-1">2. 地址线 A7 区分两个口 <a class="header-anchor" href="#_2-地址线-a7-区分两个口" aria-label="Permalink to &quot;2. 地址线 A7 区分两个口&quot;">​</a></h3><p>接下来要在一段地址里区分出<strong>命令口</strong>和<strong>数据口</strong>两个位置，靠的是地址线 A7：</p><p>（1）数据宽度配成 16 位后，HADDR 的第 8 位对应 FSMC_A7（16 位访问时地址左移一位）。</p><p>（2）所以 A7 = 0 的地址落在低位偏移 <code>0x00</code> 上，A7 = 1 落在偏移 <code>0x100</code> 上。</p><p>驱动里就把它写成两个 <code>volatile uint16_t</code> 成员——<strong>写 REG 就是写命令口，读写 DATA 就是读写数据口</strong>：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Drivers/BSP/Ethernet/dm9000.h</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typedef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    volatile</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> uint16_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> REG;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    /* 命令口, 偏移 0xFE */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    volatile</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> uint16_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DATA;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* 数据口, 偏移 0x100 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} DM9000_TypeDef;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DM9000_BASE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ((</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">64000000</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">U</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">000000FE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">U</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DM9000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      ((DM9000_TypeDef </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)DM9000_BASE)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>一次寄存器读写的实际动作就是两次内存访问：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DM9000</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REG </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> reg;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      /* 写索引: 命令口 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DM9000</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DATA;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* 读数据: 数据口 */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>发包时同理：先把 <code>MWCMD</code>（0xF2）写进命令口，之后对数据口的连续写就自动进入发送 SRAM，这也是&quot;索引 + 数据口&quot;这套访问方式的典型用法。</p><h2 id="五、-与外部-sram-共用总线的约束" tabindex="-1">五、 与外部 SRAM 共用总线的约束 <a class="header-anchor" href="#五、-与外部-sram-共用总线的约束" aria-label="Permalink to &quot;五、 与外部 SRAM 共用总线的约束&quot;">​</a></h2><h3 id="_1-fsmc-必须先初始化" tabindex="-1">1. FSMC 必须先初始化 <a class="header-anchor" href="#_1-fsmc-必须先初始化" aria-label="Permalink to &quot;1. FSMC 必须先初始化&quot;">​</a></h3><p>DM9000 与 IS62WV51216 共用 FSMC 的数据线、地址线和读写控制线，只靠片选区分，所以有两件事必须注意：</p><p>（1）<strong><code>MX_FSMC_Init()</code> 必须已经在前面跑过</strong>。FSMC 没初始化就访问 <code>0x64000000</code> 或 <code>0x68000000</code>，CPU 拿不到总线应答，直接进 HardFault。</p><p>（2）<strong>两个设备在总线上是互斥的</strong>。虽然片选由硬件自动产生，但如果收发网卡数据的过程中被别的代码插进来访问外部 SRAM，总线利用率与访问时序会相互影响——这也是后面 IAP 把 128 KB 载荷缓冲放到外部 SRAM 时，要把&quot;写索引 + 读数据&quot;这段用临界区保护起来的原因。</p><h3 id="_2-cubemx-侧的关键配置" tabindex="-1">2. CubeMX 侧的关键配置 <a class="header-anchor" href="#_2-cubemx-侧的关键配置" aria-label="Permalink to &quot;2. CubeMX 侧的关键配置&quot;">​</a></h3><h4 id="_2-1-fsmc" tabindex="-1">2.1 FSMC <a class="header-anchor" href="#_2-1-fsmc" aria-label="Permalink to &quot;2.1 FSMC&quot;">​</a></h4><p>CubeMX 左侧 Mode 面板中，在 <strong>NOR Flash/PSRAM/SRAM 2</strong> 实例上勾选 chip select，选择 <strong>SRAM</strong> 类型、<strong>16 bits</strong> 数据宽度即可；右侧 Configuration 面板生成的关键参数（对应 <code>fsmc.c</code> 里的 <code>hsram2</code>）：</p><table tabindex="0"><thead><tr><th>配置项</th><th>取值</th><th>说明</th></tr></thead><tbody><tr><td>NSBank</td><td><code>FSMC_NORSRAM_BANK2</code></td><td>对应 NE2 片选（Bank 1 NOR/PSRAM 2）</td></tr><tr><td>MemoryType</td><td><code>FSMC_MEMORY_TYPE_SRAM</code></td><td>按 SRAM 时序访问，DM9000 不属于 NOR/NAND</td></tr><tr><td>MemoryDataWidth</td><td><code>FSMC_NORSRAM_MEM_BUS_WIDTH_16</code></td><td>16 位数据总线</td></tr><tr><td>WriteOperation</td><td><code>FSMC_WRITE_OPERATION_ENABLE</code></td><td>要能写寄存器与发送 FIFO</td></tr><tr><td>ExtendedMode</td><td><code>FSMC_EXTENDED_MODE_DISABLE</code></td><td>异步模式，读/写共用一套时序</td></tr><tr><td>AccessMode</td><td><code>FSMC_ACCESS_MODE_A</code></td><td>异步模式 A</td></tr><tr><td>AddressSetupTime</td><td>0</td><td>地址建立时间 0 个 HCLK 周期</td></tr><tr><td>AddressHoldTime</td><td>15</td><td>默认值，地址/数据非复用时不起作用</td></tr><tr><td>DataSetupTime</td><td>3</td><td>数据建立时间 3 个 HCLK 周期，决定单次总线访问的时长</td></tr><tr><td>BusTurnAroundDuration</td><td>0</td><td>总线周转时间 0 个 HCLK 周期</td></tr></tbody></table><p>外部的 IS62WV51216 走的是另一个实例 <strong>NOR Flash/PSRAM/SRAM 1</strong>（<code>hsram1</code>，NE3/Bank3），时序参数与上面完全相同，这里不再赘述。</p><p>真正让&quot;地址线区分命令/数据口&quot;成立的是数据宽度这一项：它决定了地址线到 HADDR 的错位关系，也就决定了 <code>0xFE</code> / <code>0x100</code> 这两个偏移。<strong>改数据宽度前一定要回头看驱动里的偏移量</strong>，否则会出现&quot;寄存器读写全乱、ID 读出来是 0x00000000&quot;这种很像是硬件故障的现象。</p><p><img src="`+n+'" alt="image-20261015064648517"></p><h4 id="_2-2-gpio" tabindex="-1">2.2 GPIO <a class="header-anchor" href="#_2-2-gpio" aria-label="Permalink to &quot;2.2 GPIO&quot;">​</a></h4><p>FSMC 之外的普通 GPIO 只有 DM9000 的中断脚和复位脚，配置要点：</p><table tabindex="0"><thead><tr><th>引脚</th><th>模式</th><th>上下拉</th><th>作用</th></tr></thead><tbody><tr><td>PG6（DM9000_INT）</td><td><code>GPIO_MODE_IT_FALLING</code>（EXTI 下降沿中断）</td><td>内部上拉</td><td>DM9000 来包时把 INT 拉低，触发中断通知 CPU 收包</td></tr><tr><td>PD7（DM9000_RST）</td><td><code>GPIO_MODE_OUTPUT_PP</code>（推挽输出）</td><td>无上下拉</td><td>软件控制 DM9000 硬复位：<code>DM9000_Reset()</code> 里先拉低 10 ms 再拉高，等 100 ms 让内部 PHY/寄存器就绪</td></tr></tbody></table><p>两个细节值得说明：</p><p>（1）<strong>INT 配成下降沿而不是低电平触发</strong>。DM9000 的 INT 是电平保持型——包到达拉低，驱动在 EXTI 回调里写 1 清除 DM9000 的 ISR 位后 INT 才会回高。所以用下降沿即可，且回调里必须清 ISR 位，否则下降沿只出现一次，之后所有包都漏。默认初始电平上 PG6 靠上拉保持为高，空闲时不会误触发。</p><p>（2）<strong>RST 初始输出为低电平</strong>。<code>MX_GPIO_Init()</code> 先把 PD7 写成 RESET，即上电后 DM9000 被按住复位，直到 <code>DM9000_Reset()</code> 主动释放，避免芯片在上电混乱期抢总线。</p><p><img src="'+l+'" alt="image-20261015065116793"></p><h4 id="_2-3-nvic" tabindex="-1">2.3 NVIC <a class="header-anchor" href="#_2-3-nvic" aria-label="Permalink to &quot;2.3 NVIC&quot;">​</a></h4><p>PG6 对应的 EXTI 线 6 属于 <strong>EXTI9_5_IRQn</strong> 这一个中断向量（EXTI 线 5~9 共用一个向量），NVIC 里只需使能它：</p><table tabindex="0"><thead><tr><th>配置项</th><th>取值</th><th>说明</th></tr></thead><tbody><tr><td>中断向量</td><td><code>EXTI9_5_IRQn</code></td><td>入口是 <code>EXTI9_5_IRQHandler</code>，CubeMX 生成的代码在其中调用 <code>HAL_GPIO_EXTI_IRQHandler(DM9000_INT_Pin)</code>，最终分发到驱动里的 <code>HAL_GPIO_EXTI_Callback()</code></td></tr><tr><td>抢占优先级 / 子优先级</td><td>3 / 3</td><td>优先级压得比较低，收包通知不必抢占实时性要求更高的中断；同时驱动在访问 DM9000 总线时用关中断（<code>__disable_irq()</code>）做临界区，这个优先级与之配合即可</td></tr></tbody></table><p>CubeMX 里只需在 NVIC 面板勾选 <strong>EXTI line[9:5] interrupts</strong>，优先级保持默认即可。</p><p><img src="'+o+'" alt="image-20261015065140785"></p><h2 id="六、-小结与参考资料" tabindex="-1">六、 小结与参考资料 <a class="header-anchor" href="#六、-小结与参考资料" aria-label="Permalink to &quot;六、 小结与参考资料&quot;">​</a></h2><h3 id="_1-本篇小结" tabindex="-1">1. 本篇小结 <a class="header-anchor" href="#_1-本篇小结" aria-label="Permalink to &quot;1. 本篇小结&quot;">​</a></h3><ul><li>单片机接网线有全硬件协议栈与软件协议栈两条路；本板用 DM9000 + lwIP 的软件路线，好处是协议栈完全可控可裁。</li><li>DM9000 是&quot;MAC + PHY + 收发 SRAM&quot;三合一，对外是并口，靠索引/数据两个口访问寄存器。</li><li>它挂在 FSMC 的 <strong>NE2</strong> 上，片选 PG9；命令/数据靠 <strong>A7（PF13）</strong> 区分；中断 PG6、复位 PD7 是普通 GPIO。</li><li>命令口地址偏移是 <code>0xFE</code>、数据口是 <code>0x100</code>，由 FSMC 16 位数据宽度下的地址错位关系决定。</li><li>中断与复位两根线都与板上别的东西复用了（NRF_IRQ、RS485_RE），取舍要在项目初期就定下来。</li><li>与外部 SRAM 共用总线，所以 FSMC 必须最先初始化，且访问要防并发。</li></ul><h3 id="_2-参考资料" tabindex="-1">2. 参考资料 <a class="header-anchor" href="#_2-参考资料" aria-label="Permalink to &quot;2. 参考资料&quot;">​</a></h3><ul><li>原理图：<a href="https://gitee.com/docs-site/scm-reference-guide/raw/main/30-STM32%E8%B5%84%E6%96%99/01-ATK%E6%88%98%E8%88%B0-V3%E5%BC%80%E5%8F%91%E6%9D%BF%E5%8E%9F%E7%90%86%E5%9B%BE/WarShip%20STM32F1_V3.4_SCH.pdf" target="_blank" rel="noreferrer"><code>30-STM32资料/01-ATK战舰-V3开发板原理图/WarShip STM32F1_V3.4_SCH.pdf</code></a></li><li>引脚表：<a href="https://gitee.com/docs-site/scm-reference-guide/raw/main/30-STM32%E8%B5%84%E6%96%99/01-ATK%E6%88%98%E8%88%B0-V3%E5%BC%80%E5%8F%91%E6%9D%BF%E5%8E%9F%E7%90%86%E5%9B%BE/%E6%88%98%E8%88%B0V3%20IO%E5%BC%95%E8%84%9A%E5%88%86%E9%85%8D%E8%A1%A8.xlsx" target="_blank" rel="noreferrer"><code>30-STM32资料/01-ATK战舰-V3开发板原理图/战舰V3 IO引脚分配表.xlsx</code></a>（PG6 / PG9 / PD7 / PF13 等行）</li><li>手册：<a href="https://gitee.com/docs-site/scm-reference-guide/raw/main/30-STM32%E8%B5%84%E6%96%99/10-lwIP/STM32F1%20LWIP%E5%BC%80%E5%8F%91%E6%89%8B%E5%86%8C%28DM9000%E7%89%88%29_V1.1.pdf" target="_blank" rel="noreferrer"><code>30-STM32资料/10-lwIP/STM32F1 LWIP开发手册(DM9000版)_V1.1.pdf</code></a> 第一章 1.2 / 1.3 节</li><li>驱动源码：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Drivers/BSP/Ethernet/dm9000.c" target="_blank" rel="noreferrer"><code>atk-f103/Drivers/BSP/Ethernet/dm9000.c</code></a>、<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Drivers/BSP/Ethernet/dm9000.h" target="_blank" rel="noreferrer"><code>dm9000.h</code></a></li><li>FSMC 配置：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Core/Src/fsmc.c" target="_blank" rel="noreferrer"><code>atk-f103/Core/Src/fsmc.c</code></a>、<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Core/Inc/main.h" target="_blank" rel="noreferrer"><code>atk-f103/Core/Inc/main.h</code></a></li></ul><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',75)])])}const M=a(h,[["render",c]]);export{_ as __pageData,M as default};
